function fibMemo(n) {
  var memo = {};
  function f(k) {
    if (k < 2) return k;
    if (memo[k] !== undefined) return memo[k];
    memo[k] = f(k - 1) + f(k - 2);
    return memo[k];
  }
  return f(n);
}

